#include "corner-directed-spiral-path.h"

std::optional<std::vector<std::pair<std::size_t,std::size_t>>> charm::v1n7::spiral_matrix::clockwise_spiral_path(std::size_t rows,std::size_t columns,charm::v1n7::spiral_matrix::Corner start){if(rows!=0&&columns>std::numeric_limits<std::size_t>::max()/rows)return std::nullopt;if(rows==0||columns==0)return std::vector<std::pair<std::size_t,std::size_t>>{};std::vector<std::vector<bool>> seen(rows,std::vector<bool>(columns));std::array<int,4> dr{0,1,0,-1},dc{1,0,-1,0};std::size_t r=0,c=0;int direction=0;if(start==Corner::top_right){c=columns-1;direction=1;}else if(start==Corner::bottom_right){r=rows-1;c=columns-1;direction=2;}else if(start==Corner::bottom_left){r=rows-1;direction=3;}std::vector<std::pair<std::size_t,std::size_t>> out;out.reserve(rows*columns);for(std::size_t count=0;count<rows*columns;++count){out.emplace_back(r,c);seen[r][c]=true;long long nr=static_cast<long long>(r)+dr[direction],nc=static_cast<long long>(c)+dc[direction];if(nr<0||nc<0||nr>=static_cast<long long>(rows)||nc>=static_cast<long long>(columns)||seen[static_cast<std::size_t>(nr)][static_cast<std::size_t>(nc)]){direction=(direction+1)%4;nr=static_cast<long long>(r)+dr[direction];nc=static_cast<long long>(c)+dc[direction];}r=static_cast<std::size_t>(nr);c=static_cast<std::size_t>(nc);}return out;}
